void TileProcessor::release(GRK_TILE_CACHE_STRATEGY strategy)
{
   // delete image in absence of tile cache strategy
   if(strategy == GRK_TILE_CACHE_NONE)
   {
          if(image_)
                 grk_object_unref(&image_->obj);
          image_ = nullptr;
